  // 智联岗位卡片对应的 Vue 数据缓存，避免每张卡片重复深度遍历。
  const zhaopinPositionCache = new WeakMap();

  let config = loadConfig();
  let cachedPanel = null;
  // 默认仅保留于内存；用户可另行选择篡改猴专用存储，绝不写入配置或站点存储。
  let greetingAPIKey = "";

